_handleFocus() {
  this.elements.menuItems.forEach((menuItem, index) => {
    menuItem.dom.link.addEventListener("focus", () => {
      this.focusState = "self";
      this.currentChild = index;
    });
  });
  // Close the menu when focus leaves the menu
  this.dom.menu.addEventListener("focusout", (event) => {
    if (!this.dom.menu.contains(event.relatedTarget)) {
      if (this.isTopLevel) {
        this.elements.submenuToggles.forEach(toggle => {
          if (toggle.isOpen) toggle.close();
        });
      } else {
        const parentMenu = this.elements.parentMenu;
        if (parentMenu) {
          const toggle = parentMenu.elements.submenuToggles.find(t => t.elements.controlledMenu === this);
          if (toggle) toggle.close();
        }
      }
    }
  });
}
